-- Ontology 1.0.0 -> 1.1.0, methodology 2.0.0, ruleset 1.1.0 (change request 2026-11-09, ADR 0016).
-- Generated by `hai-ontology migrate-plan git:<previous> ontology` and committed as a numbered delta;
-- db/migrations/0001 stays the frozen baseline. Never edited after it is applied.
-- New vocabularies and fields for the seven focus areas (control verification, autonomous monitoring,
-- containment, evidence basis, incident response, independent auditability, human benefit), the
-- ImpactMeasure entity, PillarScore.status and EvidenceSnapshot.target_states.
-- migration plan: ontology 1.0.0 -> 1.1.0
-- generated by hai-ontology from manifest ab982d5dd2d23adf8718b7a9d296b6afc9d84444127cb35afbcb3f4d9cc01fa6
BEGIN;
-- minor: vocabularies.autonomy_level: vocabulary added
CREATE TYPE hai.autonomy_level AS ENUM ('assistive', 'supervised', 'bounded_autonomous', 'open_autonomous');
-- minor: vocabularies.containment_threat: vocabulary added
CREATE TYPE hai.containment_threat AS ENUM ('restriction_bypass', 'unauthorized_access', 'privilege_escalation', 'safeguard_disablement', 'data_exfiltration', 'boundary_violation');
-- minor: vocabularies.control_capability: vocabulary added
CREATE TYPE hai.control_capability AS ENUM ('pause', 'shutdown', 'rollback', 'override', 'isolate', 'rate_limit');
-- minor: vocabularies.focus_area: vocabulary added
CREATE TYPE hai.focus_area AS ENUM ('control_verification', 'autonomous_monitoring', 'containment_security', 'evidence_basis', 'incident_response', 'independent_auditability', 'human_benefit');
-- minor: vocabularies.impact_evidence_kind: vocabulary added
CREATE TYPE hai.impact_evidence_kind AS ENUM ('stated_intention', 'output_metric', 'outcome_metric', 'independently_evaluated');
-- minor: vocabularies.maturity_status: vocabulary added
CREATE TYPE hai.maturity_status AS ENUM ('needs_attention', 'developing', 'progressing', 'strong');
-- minor: vocabularies.observability: vocabulary added
CREATE TYPE hai.observability AS ENUM ('self_explanation', 'operator_logs', 'independent_recording');
-- minor: vocabularies.verification_method: vocabulary added
CREATE TYPE hai.verification_method AS ENUM ('document_review', 'tabletop_exercise', 'simulated_test', 'live_drill', 'red_team', 'independent_audit');
-- minor: vocabularies.claim_scope_type.impact_measure: value added
ALTER TYPE hai.claim_scope_type ADD VALUE IF NOT EXISTS 'impact_measure' AFTER 'incident';
-- minor: vocabularies.target_type.impact_measure: value added
ALTER TYPE hai.target_type ADD VALUE IF NOT EXISTS 'impact_measure' AFTER 'incident';
-- minor: entities.ImpactMeasure: entity added
CREATE TABLE hai.impact_measures (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    ontology_version text NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now(),
    created_by text NOT NULL DEFAULT coalesce(current_setting('hai.actor', true), 'unknown'),
    org_id uuid NOT NULL,
    ai_system_id uuid,
    kind hai.impact_evidence_kind NOT NULL DEFAULT 'stated_intention',
    outcome text NOT NULL,
    metric text,
    unit text,
    baseline_value numeric,
    measured_value numeric,
    population text,
    measured_at date,
    period_months integer,
    measured_by_org_id uuid,
    verifier_org_id uuid,
    source_document_id uuid,
    CONSTRAINT ck_impact_measures_ck_impact_verifier CHECK (kind <> 'independently_evaluated' OR verifier_org_id IS NOT NULL),
    CONSTRAINT ck_impact_measures_period_months_range CHECK (period_months IS NULL OR (period_months >= 1))
);

ALTER TABLE hai.impact_measures ADD CONSTRAINT fk_impact_measures_org_id FOREIGN KEY (org_id) REFERENCES hai.organizations(id);
CREATE INDEX IF NOT EXISTS ix_impact_measures_org_id ON hai.impact_measures (org_id);
ALTER TABLE hai.impact_measures ADD CONSTRAINT fk_impact_measures_ai_system_id FOREIGN KEY (ai_system_id) REFERENCES hai.ai_systems(id);
CREATE INDEX IF NOT EXISTS ix_impact_measures_ai_system_id ON hai.impact_measures (ai_system_id);
ALTER TABLE hai.impact_measures ADD CONSTRAINT fk_impact_measures_measured_by_org_id FOREIGN KEY (measured_by_org_id) REFERENCES hai.organizations(id);
CREATE INDEX IF NOT EXISTS ix_impact_measures_measured_by_org_id ON hai.impact_measures (measured_by_org_id);
ALTER TABLE hai.impact_measures ADD CONSTRAINT fk_impact_measures_source_document_id FOREIGN KEY (source_document_id) REFERENCES hai.source_documents(id);
CREATE INDEX IF NOT EXISTS ix_impact_measures_source_document_id ON hai.impact_measures (source_document_id);
ALTER TABLE hai.impact_measures ADD CONSTRAINT fk_impact_measures_verifier_org_id FOREIGN KEY (verifier_org_id) REFERENCES hai.organizations(id);
CREATE INDEX IF NOT EXISTS ix_impact_measures_verifier_org_id ON hai.impact_measures (verifier_org_id);

CREATE OR REPLACE TRIGGER trg_impact_measures_append_only BEFORE UPDATE OR DELETE ON hai.impact_measures
    FOR EACH ROW EXECUTE FUNCTION hai.refuse_change();

GRANT SELECT ON hai.impact_measures TO hai_pipeline, hai_engine, hai_reviewer, hai_api, hai_admin;
GRANT INSERT ON hai.impact_measures TO hai_pipeline, hai_api, hai_reviewer;

COMMENT ON TABLE hai.impact_measures IS 'A measured effect of the organization''s AI on people (focus area human_benefit). Separates what is intended from what is counted, what is measured in people''s lives and what an independent party evaluated. Evidence links may target it.';
COMMENT ON COLUMN hai.impact_measures.org_id IS 'The organization whose AI produced the effect.';
COMMENT ON COLUMN hai.impact_measures.ai_system_id IS 'The system, when identifiable.';
COMMENT ON COLUMN hai.impact_measures.kind IS 'Stated intention, output metric, outcome metric or independently evaluated.';
COMMENT ON COLUMN hai.impact_measures.outcome IS 'The human outcome claimed or measured, in plain words.';
COMMENT ON COLUMN hai.impact_measures.metric IS 'What was measured and how.';
COMMENT ON COLUMN hai.impact_measures.unit IS 'Unit of the values.';
COMMENT ON COLUMN hai.impact_measures.baseline_value IS 'Value before the AI application, when known.';
COMMENT ON COLUMN hai.impact_measures.measured_value IS 'Value measured.';
COMMENT ON COLUMN hai.impact_measures.population IS 'Who was affected and how many.';
COMMENT ON COLUMN hai.impact_measures.measured_at IS 'When the measurement was taken.';
COMMENT ON COLUMN hai.impact_measures.period_months IS 'Length of the measurement period; durability needs more than one period.';
COMMENT ON COLUMN hai.impact_measures.measured_by_org_id IS 'Who took the measurement.';
COMMENT ON COLUMN hai.impact_measures.verifier_org_id IS 'Independent verifier, if any. Required for independently_evaluated.';
COMMENT ON COLUMN hai.impact_measures.source_document_id IS 'The document reporting the measure.';
-- minor: entities.AISystem.autonomy_level: optional field added
ALTER TABLE hai.ai_systems ADD COLUMN IF NOT EXISTS autonomy_level hai.autonomy_level;
-- minor: entities.AISystem.monitoring_mode: optional field added
ALTER TABLE hai.ai_systems ADD COLUMN IF NOT EXISTS monitoring_mode hai.observability;
-- minor: entities.Control.capabilities: optional field added
ALTER TABLE hai.controls ADD COLUMN IF NOT EXISTS capabilities hai.control_capability[];
-- minor: entities.Control.last_exercised_at: optional field added
ALTER TABLE hai.controls ADD COLUMN IF NOT EXISTS last_exercised_at date;
-- minor: entities.Control.monitoring_mode: optional field added
ALTER TABLE hai.controls ADD COLUMN IF NOT EXISTS monitoring_mode hai.observability;
-- patch: entities.Control.can_pause_or_rollback: description changed
COMMENT ON TABLE hai.controls IS 'A governance mechanism protecting a system or the organization.';
COMMENT ON COLUMN hai.controls.org_id IS 'Owning organization.';
COMMENT ON COLUMN hai.controls.ai_system_id IS 'Protected system, when identifiable.';
COMMENT ON COLUMN hai.controls.name IS 'Control name.';
COMMENT ON COLUMN hai.controls.intended_risk IS 'The risk the control addresses.';
COMMENT ON COLUMN hai.controls.owner_role IS 'Named accountable role.';
COMMENT ON COLUMN hai.controls.threshold IS 'Measurable threshold the control enforces.';
COMMENT ON COLUMN hai.controls.monitoring IS 'How operation is monitored.';
COMMENT ON COLUMN hai.controls.can_pause_or_rollback IS 'Whether the control can halt or roll back the system. Summarises capabilities.';
COMMENT ON COLUMN hai.controls.capabilities IS 'What the control can do to the running system: pause, shut down, roll back, override, isolate, rate limit (focus area control_verification).';
COMMENT ON COLUMN hai.controls.monitoring_mode IS 'How the control''s operation is observed (focus area independent_auditability).';
COMMENT ON COLUMN hai.controls.last_exercised_at IS 'Most recent test outcome that exercised the control, if any.';
COMMENT ON COLUMN hai.controls.operational_status IS 'Lifecycle of the control.';
COMMENT ON COLUMN hai.controls.valid_from IS 'When the control came into force.';
COMMENT ON COLUMN hai.controls.valid_to IS 'When it was retired.';
-- minor: entities.EvidenceLink.focus_area: optional field added
ALTER TABLE hai.evidence_links ADD COLUMN IF NOT EXISTS focus_area hai.focus_area;
-- patch: entities.EvidenceLink.target_id: description changed
COMMENT ON TABLE hai.evidence_links IS 'The only bridge from evidence to a score. One span, one target, one criterion, six separate judgments (spec section 6).';
COMMENT ON COLUMN hai.evidence_links.span_id IS 'The quoted span.';
COMMENT ON COLUMN hai.evidence_links.target_type IS 'Kind of thing the span is about.';
COMMENT ON COLUMN hai.evidence_links.target_id IS 'Id of the organization, system, claim, control, test outcome, incident or impact measure.';
COMMENT ON COLUMN hai.evidence_links.criterion_code IS 'The one criterion this link bears on (IC-08).';
COMMENT ON COLUMN hai.evidence_links.polarity IS 'Support, contradict or neutral. Never updated (IC-01).';
COMMENT ON COLUMN hai.evidence_links.admissibility IS 'Usable in scoring at all. Changed only via review.';
COMMENT ON COLUMN hai.evidence_links.admissibility_reason IS 'Why the link is inadmissible or pending.';
COMMENT ON COLUMN hai.evidence_links.maturity_rung IS 'How far up the ladder the quote proves. Set by the classifier from the quote.';
COMMENT ON COLUMN hai.evidence_links.execution_level IS 'Per-span proof of execution.';
COMMENT ON COLUMN hai.evidence_links.evidence_class IS 'Foundational, core governance, operational or external validation.';
COMMENT ON COLUMN hai.evidence_links.independence IS 'Who stands behind the statement. Recomputed from relations.';
COMMENT ON COLUMN hai.evidence_links.source_tier IS 'Potential authority of the publisher type. Never sets maturity.';
COMMENT ON COLUMN hai.evidence_links.focus_area IS 'The one focus area the quote speaks to, when it does. Reporting only; never changes a weight.';
COMMENT ON COLUMN hai.evidence_links.proposer IS 'Who proposed the link, heuristic or provider:model.';
COMMENT ON COLUMN hai.evidence_links.relevance IS 'Proposer''s relevance estimate.';
COMMENT ON COLUMN hai.evidence_links.valid_from IS 'When the evidence was true.';
COMMENT ON COLUMN hai.evidence_links.valid_to IS 'When it stopped being true.';
COMMENT ON COLUMN hai.evidence_links.reviewer_id IS 'Reviewer who last changed admissibility.';
COMMENT ON COLUMN hai.evidence_links.supersedes_id IS 'The row this one corrects or replaces.';
-- minor: entities.EvidenceSnapshot.target_states: optional field added
ALTER TABLE hai.evidence_snapshots ADD COLUMN IF NOT EXISTS target_states jsonb;
-- patch: entities.EvidenceSnapshot.incident_states: description changed
COMMENT ON TABLE hai.evidence_snapshots IS 'Frozen copy of every link''s judgment columns, incident states and version pins. The rules engine reads only this (AT-07).';
COMMENT ON COLUMN hai.evidence_snapshots.assessment_id IS 'The assessment.';
COMMENT ON COLUMN hai.evidence_snapshots.frozen_at IS 'Freeze time; freshness is computed against it.';
COMMENT ON COLUMN hai.evidence_snapshots.manifest_hash IS 'Manifest hash at freeze time.';
COMMENT ON COLUMN hai.evidence_snapshots.span_ids IS 'Spans included.';
COMMENT ON COLUMN hai.evidence_snapshots.link_ids IS 'Links included.';
COMMENT ON COLUMN hai.evidence_snapshots.link_states IS 'Frozen judgment columns per link.';
COMMENT ON COLUMN hai.evidence_snapshots.incident_states IS 'Frozen status, severity and response timeline per targeted incident.';
COMMENT ON COLUMN hai.evidence_snapshots.target_states IS 'Frozen controls, test outcomes, AI systems and impact measures of the organization, so verification rules read only the snapshot.';
COMMENT ON COLUMN hai.evidence_snapshots.connector_runs IS 'Outcome per connector for IC-15 and IC-16.';
COMMENT ON COLUMN hai.evidence_snapshots.version_pins IS 'ontology, methodology, ruleset, prompt and model.';
COMMENT ON COLUMN hai.evidence_snapshots.snapshot_sha256 IS 'SHA-256 over the canonical snapshot content.';
-- minor: entities.Incident.contained_at: optional field added
ALTER TABLE hai.incidents ADD COLUMN IF NOT EXISTS contained_at date;
-- minor: entities.Incident.containment_threat: optional field added
ALTER TABLE hai.incidents ADD COLUMN IF NOT EXISTS containment_threat hai.containment_threat;
-- minor: entities.Incident.corrected_at: optional field added
ALTER TABLE hai.incidents ADD COLUMN IF NOT EXISTS corrected_at date;
-- minor: entities.Incident.correction_verified_at: optional field added
ALTER TABLE hai.incidents ADD COLUMN IF NOT EXISTS correction_verified_at date;
-- minor: entities.Incident.correction_verified_by_org_id: optional field added
ALTER TABLE hai.incidents ADD COLUMN IF NOT EXISTS correction_verified_by_org_id uuid;
-- minor: entities.Incident.detected_at: optional field added
ALTER TABLE hai.incidents ADD COLUMN IF NOT EXISTS detected_at date;
-- minor: entities.Incident.disclosed_at: optional field added
ALTER TABLE hai.incidents ADD COLUMN IF NOT EXISTS disclosed_at date;
-- minor: entities.Incident.checks.IC-19: check added
ALTER TABLE hai.incidents ADD CONSTRAINT ck_incidents_ic_19 CHECK (correction_verified_at IS NULL OR correction_verified_by_org_id IS NOT NULL);
-- minor: entities.PillarScore.status: optional field added
ALTER TABLE hai.pillar_scores ADD COLUMN IF NOT EXISTS status hai.maturity_status;
-- minor: entities.TestOutcome.capabilities_exercised: optional field added
ALTER TABLE hai.test_outcomes ADD COLUMN IF NOT EXISTS capabilities_exercised hai.control_capability[];
-- minor: entities.TestOutcome.method: optional field added
ALTER TABLE hai.test_outcomes ADD COLUMN IF NOT EXISTS method hai.verification_method;
-- minor: entities.TestOutcome.threats_exercised: optional field added
ALTER TABLE hai.test_outcomes ADD COLUMN IF NOT EXISTS threats_exercised hai.containment_threat[];
-- minor: relations.verified_by: relation extended with fk ImpactMeasure.verifier_org_id, fk Incident.correction_verified_by_org_id
ALTER TABLE hai.incidents ADD CONSTRAINT fk_incidents_correction_verified_by_org_id FOREIGN KEY (correction_verified_by_org_id) REFERENCES hai.organizations(id);
CREATE INDEX IF NOT EXISTS ix_incidents_correction_verified_by_org_id ON hai.incidents (correction_verified_by_org_id);
UPDATE hai.schema_versions SET ontology_version = '1.1.0', methodology_version = '2.0.0', manifest_hash = 'ab982d5dd2d23adf8718b7a9d296b6afc9d84444127cb35afbcb3f4d9cc01fa6', applied_at = now() WHERE singleton;
